inline std::string_view poolPanelMessageKeyName(PoolPanelMessageKey key){
    static constexpr std::array<std::string_view,poolPanelMessageKeyCount> names={{"pool.panel.short_title","pool.panel.short_resize","pool.panel.short_keys","pool.panel.footer_edit","pool.panel.footer_review","pool.panel.footer_browse","pool.panel.plaintext_risk","pool.panel.title","pool.panel.unsaved_suffix","pool.panel.login_exposed","pool.panel.remove_only","pool.panel.explicit_dns","pool.panel.consent_prompt","pool.panel.remove_prompt","pool.panel.editor_keys","pool.panel.leave_title","pool.panel.leave_keys","pool.panel.review_heading","pool.panel.no_runtime","pool.panel.no_downgrade","pool.panel.plaintext_exposure","pool.panel.before_absent","pool.panel.after_removed","pool.panel.donation_independent","pool.panel.current_unchanged","pool.panel.no_session_network","pool.panel.endpoint_not_verified","pool.panel.end_marker","pool.panel.configured_only","pool.panel.local_defaults"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage poolPanelMessage(std::string_view language,PoolPanelMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=poolPanelMessageKeyCount)return {};
    const auto &source=poolPanelLocalePacks()[0];const auto *selected=&source;for(const auto &pack:poolPanelLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string poolPanelEnglish(PoolPanelMessageKey key){return std::string(poolPanelMessage("en",key).text);}
